499	/**
500	 * What the shared model account is doing to this shift, and the timer that
501	 * takes the banner down if the transport goes quiet. A throttle gets no
502	 * follow-up report -- the next request simply happens later -- so the
503	 * countdown is what clears it.
504	 */
505	let workerBudget: WorkerBudgetState = WORKER_BUDGET_CLEAR;
506	let workerBudgetTimer: ReturnType<typeof setTimeout> | undefined;
