508	function setWorkerBudget(state: WorkerBudgetState): void {
509	  workerBudget = state;
510	  if (workerBudgetTimer !== undefined) clearTimeout(workerBudgetTimer);
511	  workerBudgetTimer = undefined;
512	  const message = workerBudgetMessage(state, workerModelLabel());
513	  if (!message) {
514	    setWorkerMode();
515	    return;
516	  }
517	  setWorkerMode(message, "waiting");
518	  workerBudgetTimer = setTimeout(() => setWorkerBudget(WORKER_BUDGET_CLEAR), workerBudgetHoldMs(state));
519	}
