555	interface WorkerModelResponse {
556	  text: string;
557	  queueMs: number;
558	  providerMs: number;
559	  inputTokens?: number;
560	  outputTokens?: number;
561	  cachedInputTokens?: number;
562	  finishReason?: string;
563	}
564	
565	/** Absent provider fields (no usage on this response) stay absent, not zero. */
566	function workerModelMetrics(response: WorkerModelResponse): ModelCallMetrics {
567	  return {
568	    queueMs: response.queueMs,
569	    providerMs: response.providerMs,
570	    ...(response.inputTokens !== undefined ? { inputTokens: response.inputTokens } : {}),
571	    ...(response.outputTokens !== undefined ? { outputTokens: response.outputTokens } : {}),
572	    ...(response.cachedInputTokens !== undefined ? { cachedInputTokens: response.cachedInputTokens } : {}),
573	    ...(response.finishReason !== undefined ? { finishReason: response.finishReason } : {}),
574	  };
575	}
576	
577	function attachWorkerOrchestrator(activeGame: PlayableGame): void {
578	  if (!workerModel || activeGame.name !== "restaurant-arena") return;
579	  workerActivity.length = 0;
580	  const arena = activeGame as unknown as RestaurantGame;
581	  const client = new WorkerModelClient({
582	    retries: 0,
583	    // The Rust transport bounds the provider call and starts that bound after
584	    // the request budget admits it, so queue time is not charged to the
585	    // worker. A timer here would start while the request is still in line and
586	    // abort a crew that is only waiting its turn.
587	    timeoutMs: null,
588	    complete: async (request: ModelRequest, signal: AbortSignal) => {
589	      const role = request.observation.role;
590	      const startedAt = performance.now();
591	      setWorkerStatus(role, "thinking");
592	      // A request already queued behind the account's share is not pending on
593	      // the model; the budget banner is the more specific thing to say. The
594	      // activity feed still logs the request either way -- it is a log of what
595	      // happened, not a description of the current state.
596	      if (shouldReportFallback(workerBudget)) setWorkerMode(`Pending · ${workerModelLabel()} · ${role}`, "pending");
597	      addWorkerActivity(`${role}: requested live action`);
598	      const requestId = crypto.randomUUID();
599	      const cancel = () => void invoke("cancel_worker_model", { requestId });
600	      signal.addEventListener("abort", cancel, { once: true });
601	      try {
602	        const response = await invoke<WorkerModelResponse>("complete_worker_model", {
603	          requestId,
604	          request: { systemPrompt: request.systemPrompt, turnPrompt: request.turnPrompt },
605	        });
606	        if (signal.aborted) throw new Error("model request canceled");
607	        setWorkerStatus(role, "acting");
608	        addWorkerActivity(`${role}: response received in ${Math.round(performance.now() - startedAt)}ms`);
609	        return { text: response.text, metrics: workerModelMetrics(response) };
610	      } finally {
611	        signal.removeEventListener("abort", cancel);
612	      }
613	    },
614	  });
615	  let orchestrator: WorkerOrchestrator;
616	  orchestrator = new WorkerOrchestrator(arena, {
617	    client,
618	    model: workerModel,
619	    tickIntervalMs: () => arena.tickMs() || 1_000,
620	    onError: (turn) => {
621	      if (workerOrchestrator !== orchestrator) return;
622	      setWorkerStatus(turn.role, "error");
623	      addWorkerActivity(`${turn.role}: fallback — ${turn.error ?? "invalid action"}`);
624	      // A shift held back by the shared account is waiting, not broken (#281).
625	      // Only the banner is suppressed; the feed above still records the turn.
626	      if (!shouldReportFallback(workerBudget)) return;
627	      setWorkerMode(`Fallback · ${workerModelLabel()} · ${turn.role}: ${turn.error ?? "invalid action"}`, "error");
628	    },
629	    onTick: (report: OrchestratorTick) => {
630	      if (workerOrchestrator !== orchestrator || game !== activeGame) return;
631	      for (const turn of report.turns) {
632	        if (turn.status === "accepted") {
633	          setWorkerStatus(turn.role, "acting");
634	          addWorkerActivity(`${turn.role}: applied ${turn.action?.tool ?? "action"}`);
635	        }
636	        else if (turn.status === "fallback" || turn.status === "rejected") setWorkerStatus(turn.role, "error");
637	      }
638	      // Turns landing again is proof the account is answering, whatever the
639	      // last throttle said was left on its countdown.
640	      if (report.turns.every((turn) => turn.status === "accepted")) setWorkerBudget(WORKER_BUDGET_CLEAR);
641	      drawGame();
642	    },
643	  });
644	  workerOrchestrator = orchestrator;
645	}
