    this.button(
      { x: restartX, y: bar.y + (bar.height - size) / 2, width: navWidth, height: size },
      "↻",
      "restart",
      { size: compact ? 10 : 12, tip: "Restart the shift", dispatch: () => this.onUi("restart") },
