    const helpX = restartX - pad - navWidth;
    this.button(
      { x: helpX, y: bar.y + (bar.height - size) / 2, width: navWidth, height: size },
      "?",
      "help",
      { size: compact ? 10 : 12, tip: "How to Play", dispatch: () => this.onUi("help") },
    );
    const rightEdge = helpX - pad;

