            correctionRationale: "Allergy ticket first. Clean board, clean pans.",
            text: `Prioritised the allergy ticket on ${allergyOrder.tableId ?? allergyOrder.id}.`,
            changedDecisionEventId: `evt-dec-allergy-${this.currentState.seed}`,
