export const PREVIEW_RESIZE_MESSAGE = "gamepigeon:preview-resize";

/**
 * The only frames the overlay window ever takes, in logical pixels.
 *
 * The native shell boots at whatever fits the monitor and the browser preview
 * frames an iframe, so these live here rather than in `tauri.conf.json` or
 * `preview.html`: one list both surfaces read, which is what keeps the preview
 * honest about what the packaged app looks like. See README, "Window sizes".
 */
export interface OverlaySize {
  readonly width: number;
  readonly height: number;
}

/** Boot size, and where the expand control lands when it toggles off. */
export const COMPACT_SIZE: OverlaySize = { width: 600, height: 850 };
/** The expand control's other position. */
export const EXPANDED_SIZE: OverlaySize = { width: 830, height: 900 };
/** Minimized: nothing on screen but the draggable handheld pill. */
export const PILL_SIZE: OverlaySize = { width: 144, height: 48 };
/**
 * The floor for a restored window. The pill is deliberately smaller than this,
 * so minimizing has to lower the minimum before it sets the pill size and
 * restoring has to put it back — see `minimizeToPill` in `app.ts`.
 */
export const MIN_SIZE: OverlaySize = { width: 500, height: 700 };

