/**
 * Start the one save record for a fresh run. Exactly one exists at a time: a
 * new run replaces whatever was there, which is why restarting has to be the
 * caller's decision rather than a side effect of opening a game.
 */
export function newSavedGame(
  entry: GameEntry,
  variationId: string,
  seed: number,
  ownerId: string,
  actions: readonly string[] = [],
): SavedGame {
  return {
    schemaVersion: 1,
    ownerId,
    gameId: entry.id,
    gameVersion: entry.version,
    variationId,
    seed,
    actions: actions.slice(0, MAX_ACTIONS),
  };
}

/** Persisting progress must never interrupt gameplay, so a full quota is swallowed. */
export function saveGame(saved: SavedGame, storage: Storage = localStorage): void {
  try {
    storage.setItem(STORAGE_KEY, JSON.stringify(saved));
  } catch {
    // A run that cannot be saved is still a run worth playing.
  }
}

/**
 * Record one stepped action against the live save.
 *
 * Every action goes in, accepted or not: the journal is replayed in order to
 * rebuild the run, so dropping the ones that changed nothing would only make
 * the record harder to reason about. Past `MAX_ACTIONS` the record would no
 * longer load ({@link loadSavedGame} rejects it), so it stops growing instead
 * of quietly becoming unreadable.
 */
export function appendSavedAction(saved: SavedGame, action: string): boolean {
  if (saved.actions.length >= MAX_ACTIONS) return false;
  saved.actions.push(action);
  return true;
}

/** Throws the run away. Only restarting and a completed shift do this. */
export function clearSavedGame(storage: Storage = localStorage): void {
  try {
    storage.removeItem(STORAGE_KEY);
  } catch {
    // Nothing left to do; the stale record is rejected on load at worst.
  }
}

/**
 * A seed for a brand-new run, never `previousSeed`.
 *
 * Restarting means "start over with a new run", so handing back the seed of
 * the run being replaced would silently turn restart into replay — the one
 * thing README's session-save contract says it must not be.
 */
export function randomSeed(previousSeed?: number): number {
  for (let attempt = 0; attempt < 8; attempt++) {
    const seed = Math.floor(Math.random() * 0x7fffffff);
    if (seed !== previousSeed) return seed;
  }
  // Vanishingly unlikely, but a loop that can't fail beats one that can spin.
  return previousSeed === undefined ? 1 : (previousSeed + 1) % 0x7fffffff;
}

/** Rebuild only actions that remain accepted by this version of the game. */
export function restoreGame(entry: GameEntry, saved: SavedGame): RestoredGame | null {

