/**
 * Everything that can hold a shift still, kept out of `app.ts` so the rules
 * can be tested without a window.
 *
 * Three unrelated things stop the clock and they arrive in any order: the
 * harness asks for the player's attention at a turn boundary, the player
 * collapses the overlay to the pill to get back to their terminal, and a
 * dialog (How to Play, the sign-out confirmation) takes over the screen.
 * Treating them as one boolean is what makes the overlay forget it was paused
 * after you close a dialog, or leave the shift running behind the pill. So each
 * one is recorded separately and the questions the UI actually asks --
 * *should the clock run*, *which card is on screen* -- are derived.
 */

export type OverlayModal = "how-to-play" | "sign-out";

export interface SessionState {
  /** The harness stopped and wants the player back (host `gamepigeon:pause`). */
  readonly agentPaused: boolean;
  /** Collapsed to the handheld pill: the window is 144×48 and the app is hidden. */
  readonly minimized: boolean;
  /** The dialog that currently owns the screen, if any. */
  readonly modal: OverlayModal | null;
}

/** Nothing holding anything: a shift on screen is free to run. */
export const RUNNING: SessionState = { agentPaused: false, minimized: false, modal: null };

/**
 * The harness reached a turn boundary. A player who has already minimized is
 * deliberately back in their editor, so this does not pop the window open on
 * them -- the prompt is waiting when they click the pill.
 */
export function pauseForAgent(state: SessionState): SessionState {
  return { ...state, agentPaused: true };
}

/**
 * The player chose to keep playing. Only the agent's hold is released: a
 * dialog they opened stays open, and the pill stays a pill.
 */
export function continuePlaying(state: SessionState): SessionState {
  return { ...state, agentPaused: false };
}

/**
 * The host is putting the overlay back in front (`gamepigeon:resume`, which
 * also shows and centers the native window). That is the one release that
 * un-minimizes: a pill left over from the previous turn would swallow the
 * launch the user just asked for.
 */
export function resumeFromHost(state: SessionState): SessionState {
  return { ...state, agentPaused: false, minimized: false };
}

export function minimize(state: SessionState): SessionState {
  return { ...state, minimized: true };
}

/** Clicking the pill. Whatever was holding the shift before still is. */
export function restore(state: SessionState): SessionState {
  return { ...state, minimized: false };
}

export function openModal(state: SessionState, modal: OverlayModal): SessionState {
  return { ...state, modal };
}

export function closeModal(state: SessionState): SessionState {
  return { ...state, modal: null };
}

/**
 * Whether something is holding the shift still. The engine has its own pause
 * (space, an open decision) and reports it through `tickMs()`; this is only
 * about the session around it.
 */
export function isHeld(state: SessionState): boolean {
  return state.agentPaused || state.minimized || state.modal !== null;
}

/**
 * Whether the "Paused" card is the thing on screen. A dialog is drawn over the
 * same area, and the pill replaces the whole window, so both outrank it --
 * without clearing `agentPaused`, which is what brings the card back
 * afterwards.
 */
export function pausePromptVisible(state: SessionState): boolean {
  return state.agentPaused && !state.minimized && state.modal === null;
}

/** Whether `modal` is the dialog on screen. The pill hides every dialog. */
export function modalVisible(state: SessionState, modal: OverlayModal): boolean {
  return !state.minimized && state.modal === modal;
}

