648	      const requestId = crypto.randomUUID();
649	      const cancel = () => void invoke("cancel_worker_model", { requestId });
650	      signal.addEventListener("abort", cancel, { once: true });
651	      try {
652	        const response = await invoke<WorkerModelResponse>("complete_worker_model", {
653	          requestId,
654	          request: { systemPrompt: request.systemPrompt, turnPrompt: request.turnPrompt },
