969	function getArenaEvidenceHtml(): string {
970	  if (!game || game.name !== "restaurant-arena") return "";
971	  const journal = game as unknown as { getRecordedEvents?: () => { actorId?: string; model?: unknown; toolResult?: { ok?: boolean } | null }[] };
972	  if (typeof journal.getRecordedEvents !== "function") return "";
973	  let events: { actorId?: string; model?: unknown; toolResult?: { ok?: boolean } | null }[];
974	  try {
975	    events = journal.getRecordedEvents();
976	  } catch (err) {
