981	  const manager = events.filter((event) => event.actorId === "player").length;
982	  const worker = events.length - system - manager;
983	  const rejected = events.filter((event) => event.toolResult?.ok === false).length;
984	  const modelStamped = events.filter((event) => event.model !== undefined && event.model !== null).length;
985	  // Only the authorship split gets tiles — that split is what the export is
986	  // for. The rest is one line, because a six-tile grid made a footnote look
987	  // like a scoreboard.
988	  const rows: [string, string][] = [
989	    ["System", `${system}`],
990	    ["Your handover", `${manager}`],
991	    ["Worker turns", `${worker}`],
992	  ];
