997	        .map(([label, value]) => `<span class="evidence-stat"><small>${escapeHtml(label)}</small><strong>${escapeHtml(value)}</strong></span>`)
998	        .join("")}</div>
999	      <p class="debrief-caveat">${rejected} rejected call${rejected === 1 ? "" : "s"} · ${modelStamped} stamped by a model. Counted from this run&rsquo;s journal, never inferred.</p>
