/* ── Board game-over overlay ─────────────────────────────── */
.game-end-overlay {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(6, 10, 14, 0.82);
  backdrop-filter: blur(4px);
  border-radius: inherit;
  animation: fade-in 0.25s ease-out;
}
@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
.game-end-content {
  width: 100%;
  max-width: 300px;
  text-align: center;
}
.game-end-title {
