100	}
101	
102	interface TraceEnding {
103	  reason: EpisodeEndReason;
104	  endedAtMs: number;
105	}
106	
107	/**
108	 * Replays the journal into v2 events. `ending` is null while the episode is
109	 * still being played, which keeps the prefix byte-identical to the eventual
110	 * final build — the local store rejects a chunk id whose bytes changed.
111	 */
112	function buildOverlayTraceEvents(
113	  trace: StoredOverlayTrace,
114	  ending: TraceEnding | null,
115	): TraceEvent[] {
116	  const entry = findGame(trace.gameType);
117	  if (!entry?.create) throw new Error(`Unknown recorded game: ${trace.gameType}`);
118	  const game = entry.create(trace.rulesetId);
119	  game.reset(trace.seed);
120	
121	  let sequence = 0;
122	  let observationSequence = 0;
123	  let observationId = traceId(trace, "obs", observationSequence);
124	  const elapsedUs = (atMs: number) => Math.max(0, Math.round((atMs - trace.startedAtMs) * 1_000));
125	  const event = (
126	    eventType: TraceEvent["event_type"],
127	    visibility: TraceEvent["visibility"],
128	    payload: Record<string, unknown>,
129	    atMs: number,
130	  ): TraceEvent => {
131	    sequence++;
132	    return {
133	      schema_version: 2,
134	      user_id: PENDING_USER_ID,
135	      game_id: trace.gameId,
136	      chunk_id: "chk_pending",
137	      event_id: traceId(trace, "evt", sequence),
138	      event_sequence: sequence,
139	      event_version: 1,
140	      event_type: eventType,
141	      visibility,
142	      client_time_ms: atMs,
143	      monotonic_time_us: elapsedUs(atMs),
144	      payload,
145	    } as TraceEvent;
146	  };
147	
148	  const events: TraceEvent[] = [
149	    event("episode_started", "policy", {
150	      game_type: trace.gameType,
151	      game_version: trace.gameVersion,
152	      ruleset_id: trace.rulesetId,
153	      telemetry_version: 2,
154	      platform: "overlay",
155	      viewport: trace.viewport,
156	      control_schema: trace.controlSchema,
157	      input_semantics: "engine_impulse",
158	    }, trace.startedAtMs),
159	    event("engine_checkpoint", "privileged", {
160	      state_version: 1,
161	      reason: "episode_start",
162	      state: checkpointState(game),
163	      seed: trace.seed,
164	    }, trace.startedAtMs),
165	    event("observation", "policy", {
166	      observation_id: observationId,
167	      representation: "engine_state_v1",
168	      state: clone(game.state()),
169	    }, trace.startedAtMs),
170	  ];
171	
172	  for (const recorded of trace.actions) {
173	    const scoreBefore = game.score();
174	    const control = event("control_changed", "policy", {
175	      based_on_observation_id: observationId,
176	      control: recorded.action,
177	      action: recorded.action,
178	      kind: "impulse",
179	      actor: recorded.actor,
180	    }, recorded.atMs);
181	    events.push(control);
182	
183	    const result = game.step(recorded.action);
184	    observationId = traceId(trace, "obs", ++observationSequence);
185	    events.push(event("observation", "policy", {
186	      observation_id: observationId,
187	      representation: "engine_state_v1",
188	      state: clone(game.state()),
189	      caused_by_event_id: control.event_id,
190	    }, recorded.atMs));
191	    events.push(event("outcome_changed", "policy", {
192	      score_before: scoreBefore,
193	      score_after: game.score(),
194	      score_delta: game.score() - scoreBefore,
195	      engine_reward: result.reward,
196	      reward_spec_id: "engine_v1",
197	      terminal: result.done,
198	      caused_by_event_id: control.event_id,
199	      progress: { moved: result.moved, success: result.success },
200	    }, recorded.atMs));
201	    events.push(event("engine_checkpoint", "privileged", {
202	      state_version: 1,
203	      reason: result.done ? "terminal" : result.randomEffects === undefined ? "periodic" : "random_outcome",
204	      state: checkpointState(game),
205	      ...(result.randomEffects === undefined ? {} : { random_effects: clone(result.randomEffects) }),
206	      caused_by_event_id: control.event_id,
207	    }, recorded.atMs));
208	  }
209	
210	  if (ending) {
211	    const { reason, endedAtMs } = ending;
212	    events.push(event("episode_ended", "policy", {
213	      reason,
214	      final_event_sequence: sequence + 1,
215	      final_score: game.score(),
216	      duration_us: elapsedUs(endedAtMs),
217	      completed: reason === "game_over" || reason === "won" || reason === "lost",
218	    }, endedAtMs));
219	  }
220	
221	  return events;
222	}
223	
224	function toChunks(
225	  trace: StoredOverlayTrace,
226	  groups: TraceEvent[][],
227	  applicationVersion: string,
228	): TraceEventChunk[] {
229	  return groups.map((group, index) => {
230	    const chunkId = traceId(trace, "chk", index + 1);
231	    const chunkEvents = group.map((item) => ({ ...item, chunk_id: chunkId }));
232	    return {
233	      schema_version: 2,
234	      user_id: PENDING_USER_ID,
235	      game_id: trace.gameId,
236	      game_type: trace.gameType,
237	      game_version: trace.gameVersion,
238	      chunk_id: chunkId,
239	      chunk_sequence: index + 1,
240	      first_event_sequence: chunkEvents[0]!.event_sequence,
241	      last_event_sequence: chunkEvents.at(-1)!.event_sequence,
242	      event_count: chunkEvents.length,
243	      // Derived from the chunk's own events so a chunk sealed mid-episode and
244	      // rebuilt at episode end serializes to identical bytes.
245	      created_at_ms: chunkEvents.at(-1)!.client_time_ms,
246	      client: {
247	        platform: "tui",
248	        application_version: applicationVersion,
249	        recording_sdk_version: "2",
250	      },
251	      events: chunkEvents,
252	    };
253	  });
254	}
255	
256	export function buildOverlayTraceChunks(
257	  trace: StoredOverlayTrace,
258	  reason: EpisodeEndReason,
259	  applicationVersion: string,
260	  endedAtMs = Date.now(),
261	): TraceEventChunk[] {
262	  const events = buildOverlayTraceEvents(trace, { reason, endedAtMs });
263	  return toChunks(trace, splitEvents(events), applicationVersion);
264	}
265	
266	/**
267	 * Chunks that are already full for an in-progress episode, so long games reach
268	 * the local recording store while they are still being played. The trailing
269	 * partial chunk is withheld until it fills or the episode ends.
270	 */
271	export function buildSealedOverlayTraceChunks(
272	  trace: StoredOverlayTrace,
273	  applicationVersion: string,
274	): TraceEventChunk[] {
275	  const groups = splitEvents(buildOverlayTraceEvents(trace, null));
276	  return toChunks(trace, groups.slice(0, -1), applicationVersion);
277	}
278	
279	export function buildOverlayGameResult(trace: StoredOverlayTrace): Record<string, unknown> | null {
280	  if (trace.completedScore === undefined || trace.endedAtMs === undefined) return null;
281	  return {
282	    result_id: traceId(trace, "res", 1),
283	    game_id: trace.gameId,
284	    game_type: trace.gameType,
285	    score: trace.completedScore,
286	    completed_at: new Date(trace.endedAtMs).toISOString(),
287	  };
