// ── Window chrome ─────────────────────────────────────────────────────
//
// The frame only ever takes the four sizes `tauri-bridge.ts` exports (README,
// "Window sizes"). Two of them are the expand toggle. The third is the pill,
// which is deliberately smaller than the window's own minimum, so minimizing
// has to lower that minimum before the pill size can land — Tauri clamps
// `setSize` against `setMinSize` — and restoring has to put it back.

type FrameSizeArg = Parameters<typeof windowHandle.setSize>[0];

/** The bridge hands back the real Tauri size under Tauri and a stand-in in preview. */
function frameArg(size: OverlaySize): FrameSizeArg {
  return overlayLogicalSize(size.width, size.height) as FrameSizeArg;
}

function frameSize(): OverlaySize {
  return expanded ? EXPANDED_SIZE : COMPACT_SIZE;
}

/** Put the window at whichever frame the expand control currently describes. */
async function applyFrame(): Promise<void> {
  try {
    await windowHandle.setMinSize(frameArg(MIN_SIZE));
    await windowHandle.setSize(frameArg(frameSize()));
  } catch {
    // A frame we cannot set is no reason to lose the session behind it.
  }
}

function updateResizeButton(): void {
  const button = document.querySelector<HTMLButtonElement>("#resize");
  if (!button) return;
  button.textContent = expanded ? "↙" : "↗";
  button.setAttribute("aria-label", expanded ? "Compact overlay" : "Expand overlay");
}

/**
 * The titlebar's ↗/↙. `defaultWindowSize` is the *default*, so toggling is a
 * choice about this session and is not written back over the setting.
 */
function toggleExpanded(): void {
  expanded = !expanded;
  updateResizeButton();
  void applyFrame();
}

/**
 * Collapse to the handheld pill. The shift keeps its state — `isHeld` stops the
 * clock rather than ending the run — so clicking the pill drops the player back
 * into the same tick they left.
 */
async function minimizeToPill(): Promise<void> {
  if (session.minimized) return;
  session = minimize(session);
  syncSession();
  try {
    await windowHandle.setMinSize(frameArg(PILL_SIZE));
    await windowHandle.setSize(frameArg(PILL_SIZE));
  } catch {
    // Keep `data-mode="pill"`: the app is already hidden, and a window stuck
    // at the old size showing a pill is still recoverable by clicking it.
  }
  document.querySelector<HTMLButtonElement>("#pill")?.focus();
}

/**
 * Back from the pill. The frame returns to the size the player was last at —
 * compact unless they had expanded it — never below `MIN_SIZE`, and centered,
 * because the pill may have been dragged to an edge the full window cannot fit.
 */
async function restoreFromPill(): Promise<void> {
  if (!session.minimized) return;
  session = restore(session);
  syncSession();
  await applyFrame();
  try {
    await windowHandle.center();
  } catch {
    // Off-center beats not restoring.
  }
}

/**
 * The pill is one target for two gestures: a click reopens, a drag moves the
 * window. Once `startDragging` hands the pointer to the compositor no click
 * arrives at all, so the flag only has to survive the gestures that do click.
 */
const PILL_DRAG_SLOP_PX = 3;

function bindPill(): void {
  const pill = document.querySelector<HTMLButtonElement>("#pill");
  if (!pill) return;
  let origin: { x: number; y: number } | null = null;
  let dragged = false;

  pill.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    origin = { x: event.clientX, y: event.clientY };
    dragged = false;
  });
  pill.addEventListener("pointermove", (event) => {
    if (!origin || dragged) return;
    if (Math.abs(event.clientX - origin.x) < PILL_DRAG_SLOP_PX
      && Math.abs(event.clientY - origin.y) < PILL_DRAG_SLOP_PX) return;
    dragged = true;
    origin = null;
    void windowHandle.startDragging().catch(() => undefined);
  });
  pill.addEventListener("pointerup", () => { origin = null; });
  pill.addEventListener("click", () => {
    if (dragged) {
      dragged = false;
      return;
    }
    void restoreFromPill();
  });
}

// ── Holds: the agent's pause, the pill, and the dialogs ───────────────

/**
 * Project {@link session} onto the DOM, then re-pick the advancer.
 *
 * Only called on a transition, so moving focus here is safe: whatever card just
 * took over the screen is what `Enter`/`Esc` should reach.
 */
function syncSession(): void {
  if (session.minimized) document.body.dataset.mode = "pill";
  else delete document.body.dataset.mode;

  const prompt = document.querySelector<HTMLElement>("#return-prompt");
  if (prompt) prompt.hidden = !pausePromptVisible(session);
  const howToPlay = document.querySelector<HTMLElement>("#how-to-play");
  if (howToPlay) howToPlay.hidden = !modalVisible(session, "how-to-play");
  const signOutPrompt = document.querySelector<HTMLElement>("#signout-prompt");
  if (signOutPrompt) signOutPrompt.hidden = !modalVisible(session, "sign-out");

  if (modalVisible(session, "sign-out")) document.querySelector<HTMLButtonElement>("#signout-confirm")?.focus();
  else if (modalVisible(session, "how-to-play")) document.querySelector<HTMLButtonElement>("#how-to-play-close")?.focus();
  else if (pausePromptVisible(session)) document.querySelector<HTMLButtonElement>("#return-code")?.focus();

  syncSchedulers();
}

function showModal(modal: OverlayModal): void {
  session = openModal(session, modal);
  syncSession();
}

function dismissModal(): void {
  if (session.modal === null) return;
  session = closeModal(session);
  syncSession();
}

// ── Advancing the shift ──────────────────────────────────────────────
//
// Two things can move the clock and never both: a live crew, which ends each
// of its own rounds with a `step("tick")`, or the local timer for a shift with
// no crew attached. `tickMs() === 0` is the engine saying *hold* — before the
// doors open, on an open decision, once the shift is over — and nothing
// schedules through it.

function cancelTick(): void {
  if (tickTimer !== undefined) window.clearTimeout(tickTimer);
  tickTimer = undefined;
}

function syncSchedulers(): void {
  cancelTick();
  if (screen !== "game" || !game || replaying || gameEnded || game.isOver() || isHeld(session)) {
    workerOrchestrator?.pause();
    return;
  }
  const interval = game.tickMs?.() ?? 0;
  if (workerOrchestrator) {
    if (interval > 0) workerOrchestrator.start();
    else workerOrchestrator.pause();
    return;
  }
  if (interval <= 0 || !(game.actions as readonly string[]).includes("tick")) return;
  tickTimer = window.setTimeout(() => {
    tickTimer = undefined;
    if (screen !== "game" || !game || replaying || gameEnded || game.isOver() || isHeld(session)) return;
    stepGame("tick", "environment");
    drawGame();
    if (game.isOver()) endGame();
  }, interval);
}

function drawGate(): void {
  screen = "gate";
  screenElement.innerHTML = gateMarkup();
  screenElement.dataset.screen = "gate";
  renderAccountChip();
  renderSignInBar();
}

