// ── Run lifecycle ─────────────────────────────────────────────────────

/** Anonymous preview runs get `""`, which is what the boot check compares against. */
function ownerId(): string {
  return signedInUser()?.id ?? "";
}

function activeVariation(selected: GameEntry, index: number): GameVariation {
  return selected.variations[index] ?? selected.variations[0]!;
}

/** Ticks and bot moves are the environment's; everything else came from a person. */
function traceActorFor(action: string): TraceActor {
  return action === "tick" || action === "bot_move" ? "environment" : "human";
}

/**
 * Tear down whatever run is on screen.
 *
 * `reason` submits the recording; omitting it means the run already sealed its
 * own trace (a completed shift, or a restart that submitted before rebuilding).
 * The `localStorage` save is never touched here — whether the record survives
 * is the caller's decision, and that difference is the whole session-save
 * contract in the README.
 */
function closeRun(reason?: EpisodeEndReason): void {
  cancelTick();
  stopWorkerOrchestrator();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  cancelTraceFlush();
  if (activeTrace && reason) submitTrace(activeTrace, reason);
  activeTrace = undefined;
  game = undefined;
  gameEnded = false;
}

/**
 * Put a run on screen and start its journals.
 *
 * `resumed` carries a game rebuilt by {@link restoreGame} together with the
 * record it came from, so a resumed run keeps its original seed *and* its
 * original action log — appending to the same record rather than rewriting it
 * is what makes "end the shift, resume next launch" replay the identical run.
 */
function beginRun(
  selected: GameEntry,
  variationIndex: number,
  seed: number,
  resumed?: { game: PlayableGame; saved: SavedGame },
): void {
  if (!selected.create) return;
  closeRun("user_quit");

  entry = selected;
  const menuIndex = MENU_GAMES.findIndex(({ id }) => id === selected.id);
  if (menuIndex >= 0) cursor = menuIndex;
  variationCursor = variationIndex >= 0 && variationIndex < selected.variations.length ? variationIndex : 0;
  const variation = activeVariation(selected, variationCursor);

  game = resumed?.game ?? selected.create(variation.id);
  if (!resumed) game.reset(seed);
  gameStartedAt = Date.now();
  actionsTaken = 0;
  gameEnded = false;

  savedGame = resumed?.saved ?? newSavedGame(selected, variation.id, seed, ownerId());
  saveGame(savedGame);

  activeTrace = createOverlayTrace(selected, variation.id, seed);
  // The prefix happened on an earlier launch, so it has no timestamps of its
  // own; stamping it at the trace's own start keeps elapsed time monotonic and
  // the replayed journal identical to the record it came from.
  if (resumed) {
    for (const action of resumed.saved.actions) {
      appendOverlayAction(activeTrace, action, traceActorFor(action), activeTrace.startedAtMs);
    }
    persistTrace(activeTrace);
  }
  sessionReceiptId = activeTrace.gameId;

  attachWorkerOrchestrator(game);
  // Launching is itself an answer to "come back to the terminal"; a Paused card
  // left over the shift the player just chose would be nonsense.
  session = continuePlaying(session);
  screen = "game";
  renderGameScreen();
  syncSession();

  captureOverlayEvent(
    "game.started",
    { game_type: selected.id, variation_id: variation.id },
    sessionReceiptId,
  );
}

/** Deep links (`gamepigeon:launch`, `?game=`) and the menu both land here. */
function launchGame(gameId: string, variationId?: string): void {
  const selected = findGame(gameId);
  if (!selected || !isPlayable(selected)) return;
  // The host defaults to `classic`, which most games do not have; an unknown
  // variation opens the game's first one rather than refusing the launch.
  const index = variationId ? selected.variations.findIndex(({ id }) => id === variationId) : 0;
  beginRun(selected, index, randomSeed());
}

/** The menu's Resume button, and `resumeLastGame` at boot. */
function resumeSavedGame(): boolean {
  const saved = savedGame;
  if (!saved) return false;
  const selected = findGame(saved.gameId);
  if (!selected || !isPlayable(selected)) return false;
  const restored = restoreGame(selected, saved);
  if (!restored) {
    // The record was written against rules this build no longer has, so it can
    // never be rebuilt. Drop it rather than keep offering a Resume that fails.
    savedGame = undefined;
    clearSavedGame();
    if (screen === "menu") drawMenu();
    return false;
  }
  const index = selected.variations.findIndex(({ id }) => id === saved.variationId);
  beginRun(selected, index, saved.seed, { game: restored.game, saved });
  return true;
}

/**
 * README, "Session save": restarting throws the record away and opens a
 * brand-new run of the same game and variation — a freshly randomized seed that
 * is never the seed it replaces, and an empty action log. Restart means "start
 * over with a new run", not "replay the same seed again".
 */
function restartRun(): void {
  if (!entry) return;
  const previousSeed = savedGame?.seed ?? activeTrace?.seed;
  const trace = activeTrace;
  cancelTraceFlush();
  activeTrace = undefined;
  // A restart is its own end reason, and it never submits a score.
  if (trace) submitTrace(trace, "restart");
  savedGame = undefined;
  clearSavedGame();
  beginRun(entry, variationCursor, randomSeed(previousSeed));
}

/**
 * README, "Session save": ending a shift back to the menu leaves the save
 * exactly as it was, so resuming later replays the identical run.
 */
function endShiftToMenu(): void {
  closeRun("user_quit");
  entry = undefined;
  sessionReceiptId = undefined;
  session = continuePlaying(session);
  screen = "menu";
  drawMenu();
  syncSession();
}

/**
 * The shift finished on its own. The only path that submits a score and clears
 * the save: quits keep the run, restarts throw it away, and neither counts as a
 * completed game (README, "Local score history").
 */
function endGame(): void {
  if (!game || !entry || gameEnded) return;
  gameEnded = true;
  cancelTick();
  stopWorkerOrchestrator();

  const success = game.hasWon();
  const score = game.score();
  const durationMs = Math.max(0, Date.now() - gameStartedAt);
  const variation = activeVariation(entry, variationCursor);
  const trace = activeTrace;
  cancelTraceFlush();
  activeTrace = undefined;
  if (trace) submitTrace(trace, success ? "won" : "lost", score);

  if (trace) {
    void invoke("append_local_score", {
      score: {
        game_id: trace.gameId,
        game_type: entry.id,
        variation_id: variation.id,
        // The engine can price a bad shift below zero; the score log is
        // unsigned, so the floor is 0 rather than a rejected append.
        score: Math.max(0, score),
        success,
        completed_at: new Date().toISOString(),
        duration_ms: durationMs,
        platform: "overlay",
      },
    }).then(() => refreshLocalScores()).catch(() => undefined);
  }

  // Nothing left to resume: the run reached its own end.
  savedGame = undefined;
  clearSavedGame();

  captureOverlayEvent("game.ended", {
    game_type: entry.id,
    variation_id: variation.id,
    outcome: "completed",
    score,
    success,
    duration_ms: durationMs,
    actions_taken: actionsTaken,
  }, sessionReceiptId);

  renderGameEnd(success, score);
  syncSchedulers();
}

/**
 * The end-of-shift card, drawn inside the board rather than as one of the
 * window-level dialogs so it stays with the run it describes. `game` is
 * deliberately still set at this point — the debrief, the timeline, the
 * evidence receipt and `Export Trace` all read the finished engine.
 */
function renderGameEnd(success: boolean, score: number): void {
  const board = screenElement.querySelector<HTMLElement>(".board");
  if (!board || board.querySelector(".game-end-overlay")) return;
  const isArena = game?.name === "restaurant-arena";
  const best = entry ? personalBest(entry.id, score) : undefined;
  const stats = [`Score ${score}`, best === undefined ? "" : `Personal best ${best}`]
    .filter(Boolean)
    .join(" · ");
  const exportGroup = isArena
    ? `<div class="export-trace-group">
        <button type="button" class="export-trace-btn" data-action="export-trace">Export Trace</button>
        <button type="button" class="export-trace-btn-alt" data-action="export-trace-jsonl" aria-label="Export trace as JSONL">JSONL</button>
      </div>`
    : "";
  const overlay = document.createElement("div");
  overlay.className = "game-end-overlay";
  overlay.dataset.tone = success ? "win" : "loss";
  overlay.innerHTML = `<div class="game-end-content${isArena ? " arena-end-content" : ""}">
    <h2 class="game-end-title">${success ? "Shift complete" : "Shift over"}</h2>
    <p class="game-end-stats">${escapeHtml(stats)}</p>
    ${getArenaDebriefHtml()}
    ${getArenaTimelineHtml()}
    ${getArenaEvidenceHtml()}
    ${sessionReceiptHtml()}
    <div class="game-end-actions">
      <button type="button" class="primary" data-restart>↻ Play again</button>
      <button type="button" data-end-menu>Menu</button>
      ${exportGroup}
    </div>
  </div>`;
  board.appendChild(overlay);
  overlay.querySelector<HTMLButtonElement>("[data-restart]")?.focus();
}

