function performAction(action: string): boolean {
  if (!game || replaying || game.isOver() || !(game.actions as readonly string[]).includes(action)) return false;
  workerOrchestrator?.pause();
  const actor = traceActorFor(action);
  const result = stepGame(action, actor);
  // Only what a person did counts towards the run's action budget; the clock
  // ticking is not a move the player made.
  if (actor === "human") actionsTaken++;

  drawGame();
  if (game.isOver()) endGame();
  return result.moved;
}

function stepGame(action: string, actor: TraceActor): StepResult {
  if (!game) throw new Error("No active game");
  const result = game.step(action);
  journalAction(action, actor);
  return result;
}

/**
 * Both journals, in one place: the recording trace and the resumable save.
 *
 * The orchestrator steps its own `tick` at the end of each round without going
 * through {@link stepGame}, so it calls this directly (see `onTick`) — a save
 * that skipped the crew's ticks would rebuild a shorter shift on the next
 * launch. Note the save can only carry actions from `game.actions`: a live
 * crew's envelopes are not replayable from a `SavedGame`, so a resumed arena run
 * reaches the same tick with the deterministic crew.
 */
function journalAction(action: string, actor: TraceActor): void {
  if (activeTrace) {
    appendOverlayAction(activeTrace, action, actor);
    persistTrace(activeTrace);
    scheduleTraceFlush(activeTrace);
  }
  if (savedGame && !replaying && appendSavedAction(savedGame, action)) saveGame(savedGame);
}

