    const char = key.char.toLowerCase();
    if (char === "r") return restartRun();
    if (key.char === "?") return showModal("how-to-play");
  }
  if (game.isOver()) {
    // The end-of-shift card owns the keyboard; its buttons cannot see `Enter`
    // themselves because the dispatch above already called preventDefault().
    if (key === "enter") restartRun();
    return;
  }
  const action = genericAction(key);
  if (action) {
    performAction(action);
