arguments.new_string:
function dismissModal(): void {
  if (session.modal === null) return;
  session = closeModal(session);
  syncSession();
}

/**
 * "Back to coding" on the Paused card. The card is answered, so the agent's hold
 * is released — but the shift is not resumed: collapsing to the pill keeps
 * `isHeld` true, so the clock is still stopped when the player clicks it and
 * they land on exactly the tick they walked away from.
 */
async function backToCoding(): Promise<void> {
  session = continuePlaying(session);
  await minimizeToPill();
}

/** "Continue playing" on the Paused card: stay on the board, clock running. */
function continueShift(): void {
  session = continuePlaying(session);
  syncSession();
}

function requestSignOut(): void {
  showModal("sign-out");
}

/**
 * Sign out and drop back to the gate.
 *
 * The `localStorage` record is deliberately left alone: it carries the
 * `ownerId` that wrote it, so signing back in finds the run again while any
 * other account's boot check refuses it. Only the in-memory handle is dropped,
 * which is what stops the gate from offering someone else's shift.
 */
async function confirmSignOut(): Promise<void> {
  try {
    await signOut();
  } catch (err) {
    // auth.ts leaves the session intact when the native delete fails, so the
    // one thing not to do here is report a sign-out that did not happen.
    console.error("Sign-out failed:", err);
    const confirmButton = document.querySelector<HTMLButtonElement>("#signout-confirm");
    if (confirmButton) {
      const original = confirmButton.innerHTML;
      confirmButton.innerHTML = "Could not sign out";
      window.setTimeout(() => { confirmButton.innerHTML = original; }, 2_000);
    }
    return;
  }
  closeRun("user_quit");
  entry = undefined;
  savedGame = undefined;
  sessionReceiptId = undefined;
  session = SESSION_RUNNING;
  drawGate();
  syncSession();
}

