document.querySelector("#account-chip")?.addEventListener("click", () => {
  if (isSignedIn()) requestSignOut();
  else void beginSignIn();
});
// The gate's sign-in button is handled by the screen click delegation above,
// since it isn't in the DOM yet at bind time.

// ── Static chrome ─────────────────────────────────────────────────────
//
// Everything below is in index.html from the first paint, so it binds once.
// The titlebar itself carries `data-tauri-drag-region`, so dragging the window
// is the webview's job, not ours.

document.querySelector("#resize")?.addEventListener("click", toggleExpanded);
document.querySelector("#hide")?.addEventListener("click", () => void minimizeToPill());
document.querySelector("#shutdown")?.addEventListener("click", () => {
  // The native side records the shutdown flag and ends the process; the run's
  // trace still has to be handed over first, and a shutdown submits no score.
  closeRun("client_closed");
  void invoke("shutdown").catch(() => undefined);
});

document.querySelector("#return-code")?.addEventListener("click", () => void backToCoding());
document.querySelector("#continue-game")?.addEventListener("click", continueShift);
document.querySelector("#how-to-play-from-pause")?.addEventListener("click", () => showModal("how-to-play"));
document.querySelector("#return-menu")?.addEventListener("click", endShiftToMenu);
document.querySelector("#how-to-play-close")?.addEventListener("click", dismissModal);
document.querySelector("#signout-confirm")?.addEventListener("click", () => void confirmSignOut());
document.querySelector("#signout-cancel")?.addEventListener("click", dismissModal);
bindPill();

// ── Host events ───────────────────────────────────────────────────────
//
// The native shell reaches the webview by dispatching these on `window`
// (`dispatch_overlay_event` / `dispatch_launch` in tauri/src/main.rs).

window.addEventListener("gamepigeon:launch", (event) => {
  const detail = (event as CustomEvent<{ game?: unknown; variation?: unknown }>).detail;
  if (typeof detail?.game !== "string") return;
  launchGame(detail.game, typeof detail.variation === "string" ? detail.variation : undefined);
});

/**
 * `Stop`: the harness reached a turn boundary and wants the player back. A
 * launch may have arrived in the same batch, so this only sets the hold — the
 * card is drawn over whatever ends up on screen.
 */
window.addEventListener("gamepigeon:pause", () => {
  if (!settings.autoPauseOnStop) return;
  session = pauseForAgent(session);
  syncSession();
});

/** `UserPromptSubmit`: the window is being shown, so no pill may survive it. */
window.addEventListener("gamepigeon:resume", () => {
  session = resumeFromHost(session);
  syncSession();
  void applyFrame();
});

/**
 * `SessionStart`: snap a still-running overlay back to the menu so a new session
 * never resumes mid-game. The save survives untouched — this is the host's
 * version of ending a shift, and the run is still there to resume.
 */
window.addEventListener("gamepigeon:reset", () => {
  if (!settings.resetOnNewSession) return;
  if (screen === "game") endShiftToMenu();
  session = SESSION_RUNNING;
  syncSession();
});

window.addEventListener("gamepigeon:auth-success", (event) => {
  clearSignInPending();
  setSignInStatus("idle", "");
  // The event carries only the address; the id the save record is keyed to
  // comes from the stored session.
  void loadAuthSession().then((user) => {
    const detail = (event as CustomEvent<{ email?: unknown }>).detail;
    const resolved = user
      ?? (typeof detail?.email === "string" ? { id: "", email: detail.email } : null);
    if (resolved) enterArcade(resolved);
  });
});

window.addEventListener("gamepigeon:auth-error", (event) => {
  clearSignInPending();
  const detail = (event as CustomEvent<unknown>).detail;
  setSignInStatus("error", typeof detail === "string" && detail ? detail : "Sign-in failed. Try again.");
});

window.addEventListener("gamepigeon:sync-error", (event) => {
  const detail = (event as CustomEvent<unknown>).detail;
  setSyncError(typeof detail === "string" && detail ? detail : "Gameplay sync is paused.");
});

window.addEventListener("gamepigeon:sync-success", () => setSyncError(null));

// A run in progress when the window goes away still has a journal worth keeping.
window.addEventListener("pagehide", () => {
  if (activeTrace) submitTrace(activeTrace, "client_closed");
});

bindUpdateBanner();
void refreshUpdateBanner();

/**
 * A session exists: load whatever run belongs to this account and show the
 * arcade. The record carries the `ownerId` that wrote it, so another account's
 * shift is never offered — the record itself is left in place for them.
 */
function enterArcade(user: AuthUser): void {
  const saved = loadSavedGame();
  savedGame = saved?.ownerId === user.id ? saved : undefined;
  unlockTui(user);
  if (settings.resumeLastGame && savedGame) resumeSavedGame();
  refreshLocalScores();
}

void loadSettings().then(async () => {
  workerModel = await invoke<TraceV3Model | undefined>("read_worker_model_config").catch(() => undefined);
  captureOverlayEvent("app.opened", { app_version: typeof __APP_VERSION__ !== "undefined" ? __APP_VERSION__ : "0.2.0", platform: "overlay" });
  // The native window boots at whatever fits the monitor; the documented frames
  // are the frontend's to apply (README, "Window sizes").
  updateResizeButton();
  await applyFrame();
  syncSession();

  if (!isTauri()) {
    const params = new URLSearchParams(window.location.search);
    if (params.get("scores") === "demo") localScores = PREVIEW_SCORES;
    // Preview runs are unowned, so they match the `""` an unsigned-in save carries.
    enterArcade({ id: "", email: "preview@localhost" });
    const requested = params.get("game");
    if (requested) launchGame(requested, params.get("variation") ?? undefined);
  } else {
    void loadAuthSession().then((user) => {
      if (user) {
        enterArcade(user);
        void invoke<string | null>("read_sync_error").then(setSyncError).catch(() => {});
        recoverTraces();
      }
      else drawGate();
    });
  }
});

