import { describe, expect, test } from "bun:test";
import {
  RUNNING,
  closeModal,
  continuePlaying,
  isHeld,
  minimize,
  modalVisible,
  openModal,
  pauseForAgent,
  pausePromptVisible,
  restore,
  resumeFromHost,
} from "./pause-state.js";

describe("session holds", () => {
  test("a running session holds nothing", () => {
    expect(isHeld(RUNNING)).toBe(false);
    expect(pausePromptVisible(RUNNING)).toBe(false);
    expect(modalVisible(RUNNING, "how-to-play")).toBe(false);
  });

  test("each of the three holds stops the clock on its own", () => {
    expect(isHeld(pauseForAgent(RUNNING))).toBe(true);
    expect(isHeld(minimize(RUNNING))).toBe(true);
    expect(isHeld(openModal(RUNNING, "sign-out"))).toBe(true);
  });

  test("releasing one hold leaves the others in place", () => {
    const held = openModal(minimize(pauseForAgent(RUNNING)), "how-to-play");
    const kept = continuePlaying(held);
    expect(kept.agentPaused).toBe(false);
    expect(kept.minimized).toBe(true);
    expect(kept.modal).toBe("how-to-play");
    expect(isHeld(kept)).toBe(true);
  });

  test("every transition leaves the input untouched", () => {
    const before = pauseForAgent(RUNNING);
    minimize(before);
    openModal(before, "sign-out");
    continuePlaying(before);
    expect(before).toEqual({ agentPaused: true, minimized: false, modal: null });
  });
});

describe("the agent's pause", () => {
  test("does not pop the window open on a player who already left", () => {
    const paused = pauseForAgent(minimize(RUNNING));
    expect(paused.minimized).toBe(true);
    // The prompt is waiting behind the pill rather than drawn over it.
    expect(pausePromptVisible(paused)).toBe(false);
    expect(pausePromptVisible(restore(paused))).toBe(true);
  });

  test("survives a dialog opening and closing over it", () => {
    const paused = pauseForAgent(RUNNING);
    const withDialog = openModal(paused, "how-to-play");
    expect(pausePromptVisible(withDialog)).toBe(false);
    expect(modalVisible(withDialog, "how-to-play")).toBe(true);
    expect(pausePromptVisible(closeModal(withDialog))).toBe(true);
  });
});

describe("resumeFromHost", () => {
  test("un-minimizes, because the host is showing the window", () => {
    const resumed = resumeFromHost(pauseForAgent(minimize(RUNNING)));
    expect(resumed).toEqual({ agentPaused: false, minimized: false, modal: null });
    expect(isHeld(resumed)).toBe(false);
  });

  test("is the only release that does — continuePlaying keeps the pill", () => {
    expect(continuePlaying(minimize(RUNNING)).minimized).toBe(true);
  });
});

describe("what is on screen", () => {
  test("the pill replaces every dialog", () => {
    const pill = minimize(openModal(RUNNING, "sign-out"));
    expect(modalVisible(pill, "sign-out")).toBe(false);
    expect(modalVisible(restore(pill), "sign-out")).toBe(true);
  });

  test("only the open dialog reports itself visible", () => {
    const state = openModal(RUNNING, "how-to-play");
    expect(modalVisible(state, "how-to-play")).toBe(true);
    expect(modalVisible(state, "sign-out")).toBe(false);
  });

  test("closing a dialog with nothing behind it leaves the shift free", () => {
    expect(isHeld(closeModal(openModal(RUNNING, "how-to-play")))).toBe(false);
  });
});

