  test("each of the three holds stops the clock on its own", () => {
    expect(isHeld(pauseForAgent(RUNNING))).toBe(true);
    expect(isHeld(minimize(RUNNING))).toBe(true);
    expect(isHeld(openModal(RUNNING, "sign-out"))).toBe(true);
  });

