    expect(pausePromptVisible(paused)).toBe(false);
    expect(pausePromptVisible(restore(paused))).toBe(true);
  });

  test("survives a dialog opening and closing over it", () => {
    const paused = pauseForAgent(RUNNING);
    const withDialog = openModal(paused, "how-to-play");
    expect(pausePromptVisible(withDialog)).toBe(false);
    expect(modalVisible(withDialog, "how-to-play")).toBe(true);
