  test("un-minimizes, because the host is showing the window", () => {
    const resumed = resumeFromHost(pauseForAgent(minimize(RUNNING)));
    expect(resumed).toEqual({ agentPaused: false, minimized: false, modal: null });
    expect(isHeld(resumed)).toBe(false);
  });

  test("is the only release that does — continuePlaying keeps the pill", () => {
    expect(continuePlaying(minimize(RUNNING)).minimized).toBe(true);
  });
});

describe("what is on screen", () => {
  test("the pill replaces every dialog", () => {
    const pill = minimize(openModal(RUNNING, "sign-out"));
    expect(modalVisible(pill, "sign-out")).toBe(false);
    expect(modalVisible(restore(pill), "sign-out")).toBe(true);
  });

  test("only the open dialog reports itself visible", () => {
    const state = openModal(RUNNING, "how-to-play");
    expect(modalVisible(state, "how-to-play")).toBe(true);
    expect(modalVisible(state, "sign-out")).toBe(false);
  });

  test("closing a dialog with nothing behind it leaves the shift free", () => {
    expect(isHeld(closeModal(openModal(RUNNING, "how-to-play")))).toBe(false);
  });
});

