import { describe, expect, test } from "bun:test";
import {
  COMPACT_SIZE,
  EXPANDED_SIZE,
  MIN_SIZE,
  PILL_SIZE,
  PREVIEW_RESIZE_MESSAGE,
  isTauri,
} from "./tauri-bridge.js";

/**
 * README, "Window sizes", names these four exports and their exact values, and
 * `overlay/preview.html` frames the browser preview at the compact one. A change
 * here is a change to documented behaviour, so it has to be a deliberate one.
 */
describe("overlay frames", () => {
  test("match the sizes the README documents", () => {
    expect(COMPACT_SIZE).toEqual({ width: 600, height: 850 });
    expect(EXPANDED_SIZE).toEqual({ width: 830, height: 900 });
    expect(PILL_SIZE).toEqual({ width: 144, height: 48 });
    expect(MIN_SIZE).toEqual({ width: 500, height: 700 });
  });

  test("expanded is larger than compact in both directions", () => {
    expect(EXPANDED_SIZE.width).toBeGreaterThan(COMPACT_SIZE.width);
    expect(EXPANDED_SIZE.height).toBeGreaterThan(COMPACT_SIZE.height);
  });

  test("every frame the expand control reaches clears the minimum", () => {
    for (const size of [COMPACT_SIZE, EXPANDED_SIZE]) {
      expect(size.width).toBeGreaterThanOrEqual(MIN_SIZE.width);
      expect(size.height).toBeGreaterThanOrEqual(MIN_SIZE.height);
    }
  });

  test("the pill is below the minimum, so minimizing has to lower it first", () => {
    // This is what `minimizeToPill` in app.ts works around: Tauri clamps
    // setSize against setMinSize, so the pill can never land without the floor
    // coming down with it.
    expect(PILL_SIZE.width).toBeLessThan(MIN_SIZE.width);
    expect(PILL_SIZE.height).toBeLessThan(MIN_SIZE.height);
  });
});

describe("preview fallbacks", () => {
  test("no Tauri internals means preview mode", () => {
    expect(isTauri()).toBe(false);
  });

  test("the preview resize message is the one preview.html listens for", () => {
    expect(PREVIEW_RESIZE_MESSAGE).toBe("gamepigeon:preview-resize");
  });
});

